use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record};
#[test]
fn native_identity_semantics_preserve_original_branches_and_cancel_every_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let body=law["bodyBytes"].as_u64().unwrap()as usize;
 for case in law["cases"].as_array().unwrap(){let field=if case["field"]=="name"{IdentityField::Name}else{IdentityField::Version};let mut wire=corpus()["model"].clone();wire[case["field"].as_str().unwrap()]=case["before"].clone();let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=wire;let outer=receive::<crate::snapshot::original::EnergyModelSnapshot>(&document);let original=source(outer);let payload=source(case["value"].as_str().unwrap().to_owned());
  for cutoff in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=IdentityChangePreparation::new(field);let mut turns=0;
   while !owner.decision_ready()&&cutoff.is_none_or(|cut|turns<cut){let d=owner.decision_demand(payload.borrow(),original.borrow(),body).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),body,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(payload.borrow(),original.borrow(),body).unwrap(),d);}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),body,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;assert!(turns<10000);}
   if cutoff.is_none(){let status=owner.outcome().unwrap();assert_eq!(status.as_str(),case["outcome"].as_str().unwrap());if status==IdentityOutcome::Changed{let g=grant(owner.take_decision_demand().unwrap());let(diff,p)=owner.take_decision(g).unwrap().unwrap();assert!(p.fits(g));let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));assert_eq!(field.text(post.model.identity.get()),case["after"].as_str().unwrap());assert_eq!(post.model.geometry.identity(),original.borrow().get().model.geometry.identity());drain(post);drain(diff);while !owner.inverse_ready(){let g=grant(owner.inverse_demand(original.borrow(),body).unwrap());let(s,h)=observe(||owner.inverse(original.borrow(),body,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}let g=grant(owner.take_inverse_demand().unwrap());let(value,_)=owner.take_inverse(g).unwrap().unwrap();assert_eq!(value,case["before"].as_str().unwrap());drain(value);}}
   owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let g=grant(owner.close_demand(body).unwrap());let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(field.text(original.borrow().get().model.identity.get()),case["before"].as_str().unwrap());
  }drain(payload);drain(original);
 }
}

#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
struct IdentityOperation{value:String}
impl protocol::Mutation<EnergyModelSnapshot> for IdentityOperation{
 type Diff=EnergyModelDiff;
 const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];
 fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("fixture only exercises the original retained semantic ports")}
}
impl IdentityPayload<IdentityOperation> for IdentityOperation{
 const FIELD:IdentityField=IdentityField::Name;
 const INVALID:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Fatal,code:"mutation.invariant",message:"An energy model name must not be blank."};
 const UNCHANGED:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Warning,code:"mutation.no-op",message:"The energy model already has this name."};
 fn source(payload:RetainedCloneRef<'_,Self>)->RetainedCloneRef<'_,String>{payload.project(0,|p|&p.value)}
 fn inverse(value:String)->IdentityOperation{Self{value}}
}
#[test]
fn native_identity_leaf_owns_original_diagnostics_and_exact_inverse_issuer(){
 use protocol::mutation::retained::{RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
 type Owner=IdentityLeafPreparation<IdentityOperation,IdentityOperation>;
 assert!(std::mem::size_of::<Owner>()<=4096,"actual native identity leaf frame={} core={} exceeds one bounded birth",std::mem::size_of::<Owner>(),std::mem::size_of::<IdentityChangePreparation>());
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter().filter(|case|case["field"]=="name"){
  let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();document["model"]["name"]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let payload=source(IdentityOperation{value:case["value"].as_str().unwrap().into()});
  for cutoff in std::iter::once(None).chain((0..160).map(Some)){
   let mut owner=Owner::new();let mut ready=false;
   for _ in 0..cutoff.unwrap_or(10000){let d=owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in helpers::denied_axes(g,d){let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}
   let mut rows=None;let mut diff=None;if cutoff.is_none(){assert!(ready);match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert_eq!(case["outcome"],"refused");assert_eq!(messages.len(),1);assert_eq!(messages[0].target,vec![payload.borrow().get().value.as_str()]);assert_eq!(messages[0].code.0,"mutation.invariant");close_messages(messages);},RetainedMutationDecision::Admitted(value,messages)=>{assert_ne!(case["outcome"],"refused");assert_eq!(messages.len(),usize::from(case["outcome"]=="no-op"));close_messages(messages);let original_diff=source(value);for _ in 0..10000{let d=owner.inverse_demand(payload.borrow(),original.borrow(),original_diff.borrow(),4096).unwrap();let g=grant(d);let(s,h)=observe(||owner.inverse(payload.borrow(),original.borrow(),original_diff.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){rows=Some(owner.take_inverse());break;}}assert_eq!(rows.as_ref().unwrap().len(),usize::from(case["outcome"]=="changed"));if let Some(row)=rows.as_ref().unwrap().first(){assert_eq!(row.value,case["before"].as_str().unwrap());}diff=Some(original_diff);}}}
   if cutoff.is_some()&&ready{match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>close_messages(messages),RetainedMutationDecision::Admitted(value,messages)=>{close_messages(messages);let original_diff=source(value);for _ in 0..cutoff.unwrap(){let g=grant(owner.inverse_demand(payload.borrow(),original.borrow(),original_diff.borrow(),4096).unwrap());let(s,h)=observe(||owner.inverse(payload.borrow(),original.borrow(),original_diff.borrow(),4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){break;}}diff=Some(original_diff);}}}
   let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<IdentityOperation>::default();let context=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(context,4096).unwrap();let g=grant(d);for denied in helpers::denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(rows)=rows{drain(rows);}if let Some(diff)=diff{drain(diff);}
  }drain(payload);drain(original);
 }
}

fn close_messages(messages:Vec<protocol::MutationMessage>){let mut owner=protocol::MutationMessageLedgerRetirement::new(String::new(),messages);for _ in 0..10000{if owner.terminal_is_empty(){return;}let d=RetirementDemand{copy_bytes:owner.next_copy_byte_demand(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("original identity diagnostics did not close");}
